/* ===== v35: report settimanale nell'app (si apre all'inizio di ogni settimana) ===== */
function jrWeekReport(force){
  try{
    if(typeof cfg==='undefined'||!cfg||!cfg.name) return;
    var now=new Date(), m=new Date(now.getFullYear(),now.getMonth(),now.getDate()); m.setDate(m.getDate()-((m.getDay()+6)%7));
    var iso=function(d){ return d.getFullYear()+'-'+('0'+(d.getMonth()+1)).slice(-2)+'-'+('0'+d.getDate()).slice(-2); };
    var thisMon=iso(m), pm=new Date(m); pm.setDate(pm.getDate()-7); var prevMon=iso(pm), nm=new Date(m); nm.setDate(nm.getDate()+7); var nextMon=iso(nm);
    if(!force){ if(ld('jr-wrep','')===thisMon) return; }
    var all=jrAll(), me=cfg.name, tN=iso(now);
    var last=all.filter(function(a){ return a.d>=prevMon&&a.d<thisMon&&jrMine(a); });
    var nowW=all.filter(function(a){ return a.d>=thisMon&&a.d<nextMon&&jrMine(a); });
    var given=0, got=0, refused=0;
    all.forEach(function(a){ if(a.d<prevMon||a.d>=thisMon||!a.w) return; var o=a.r?a.o:me; if(a.ack==='no'){ if(o===me||a.w===me) refused++; return; } var x=jrAff(a); if(!x) return; if(x.by===me) given++; if(x.who===me) got++; });
    var ren=0; try{ (port||[]).forEach(function(c){ var r=(typeof hasRenew==='function'&&hasRenew(c))?renewDays(c):null; if(r!==null&&r>=0&&r<=7) ren++; }); }catch(e){}
    var pend=all.filter(function(a){ return a.w===me&&!a.ack&&a.d>=tN&&(a.r?a.o:me)!==me; }).length;
    var first=(me.split(' ')[0]||me);
    var parts=['📊 <b>Buona settimana, '+first+'</b>'];
    parts.push('<small>Scorsa: '+last.length+' appuntament'+(last.length===1?'o':'i')+(given?' · '+given+' affianc'+(given===1?'ato':'ati'):'')+(got?' · '+got+' ricevut'+(got===1?'o':'i'):'')+(refused?' · '+refused+' rifiutat'+(refused===1?'o':'i'):'')+'</small>');
    parts.push('<small>Questa: '+nowW.length+' in agenda'+(pend?' · <b>'+pend+' da confermare</b>':'')+(ren?' · '+ren+' rinnov'+(ren===1?'o':'i')+' entro 7 gg':'')+'</small>');
    sv('jr-wrep',thisMon);
    jrBanner(parts.join('<br>'),function(){ if(pend){ try{ jrGo(tN); }catch(e){} } else { try{ setView('sum'); }catch(e){} } });
  }catch(e){}
}
window.__jrWeekReport=jrWeekReport;
setTimeout(jrWeekReport,9200);
document.addEventListener('visibilitychange',function(){ if(!document.hidden) setTimeout(jrWeekReport,1600); });


